/* Review and run against InfinityBilling. Additive/idempotent; does not delete TOTP data. SQL Server 2016. */
SET XACT_ABORT ON; BEGIN TRANSACTION;
IF OBJECT_ID(N'dbo.CostingAuthenticatorPermission',N'U') IS NULL CREATE TABLE dbo.CostingAuthenticatorPermission(EmployeeCode nvarchar(30) NOT NULL CONSTRAINT PK_CostingAuthenticatorPermission PRIMARY KEY,IsAllowed bit NOT NULL CONSTRAINT DF_CostingPermission_Allowed DEFAULT(0),ModifiedByCode nvarchar(30) NOT NULL,ModifiedOnUtc datetime2(0) NOT NULL CONSTRAINT DF_CostingPermission_Modified DEFAULT(SYSUTCDATETIME()),RowVersion rowversion NOT NULL);
IF OBJECT_ID(N'dbo.CostingAuthorizationSession',N'U') IS NULL BEGIN CREATE TABLE dbo.CostingAuthorizationSession(AuthorizationSessionId bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_CostingAuthorizationSession PRIMARY KEY,EmployeeCode nvarchar(30) NOT NULL,WebSessionId nvarchar(88) NOT NULL,GrantedOnUtc datetime2(0) NOT NULL,ExpiresOnUtc datetime2(0) NOT NULL,RevokedOnUtc datetime2(0) NULL,CONSTRAINT FK_CostingSession_Permission FOREIGN KEY(EmployeeCode) REFERENCES dbo.CostingAuthenticatorPermission(EmployeeCode));CREATE INDEX IX_CostingSession_Lookup ON dbo.CostingAuthorizationSession(EmployeeCode,WebSessionId,ExpiresOnUtc) INCLUDE(RevokedOnUtc);END;
IF OBJECT_ID(N'dbo.CostingSecurityAudit',N'U') IS NULL BEGIN CREATE TABLE dbo.CostingSecurityAudit(AuditId bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_CostingSecurityAudit PRIMARY KEY,EmployeeCode nvarchar(30) NULL,ActorEmployeeCode nvarchar(30) NULL,ActionName nvarchar(50) NOT NULL,Succeeded bit NOT NULL,OccurredOnUtc datetime2(0) NOT NULL,IpAddress varchar(45) NULL,Detail nvarchar(250) NULL);CREATE INDEX IX_CostingAudit_EmployeeDate ON dbo.CostingSecurityAudit(EmployeeCode,OccurredOnUtc DESC);END;
IF OBJECT_ID(N'dbo.CostingEmailOtpChallenge',N'U') IS NULL BEGIN
 CREATE TABLE dbo.CostingEmailOtpChallenge(ChallengeId bigint IDENTITY(1,1) NOT NULL CONSTRAINT PK_CostingEmailOtpChallenge PRIMARY KEY,EmployeeCode nvarchar(30) NOT NULL,WebSessionId nvarchar(88) NOT NULL,Purpose nvarchar(50) NOT NULL,OtpHash varbinary(32) NOT NULL,OtpSalt varchar(48) NOT NULL,RequestedOnUtc datetime2(0) NOT NULL,ExpiresOnUtc datetime2(0) NOT NULL,AttemptCount int NOT NULL,LockedUntilUtc datetime2(0) NULL,UsedOnUtc datetime2(0) NULL,InvalidatedOnUtc datetime2(0) NULL,CONSTRAINT FK_CostingEmailOtp_Permission FOREIGN KEY(EmployeeCode) REFERENCES dbo.CostingAuthenticatorPermission(EmployeeCode));
 CREATE INDEX IX_CostingEmailOtp_Lookup ON dbo.CostingEmailOtpChallenge(EmployeeCode,WebSessionId,Purpose,ChallengeId DESC);
END;
COMMIT;
